"""Step 2 (CONTEXT §6g): critics and image metrics that work on *new* images (generated by SD), on the GPU.

  TasteReward    the RL reward r(x) = z . U(f_clip(x)): frozen CLIP-L/14 (same weights/preprocessing as
                 phase_b_embed.py, done in torch on the GPU) + the recovered Phase C trunk (checkpoints/rl/trunk.pt,
                 made by rl_setup.py) + the user's z (9 weights; z = mu gives the consensus / "average taste" actor).
  SiglipCritic   held-out critic, never optimised: frozen SigLIP2 + Phase B consensus head + per-user linear residual.
  Encoders       SigLIP2 image/text (prompt fit) and DINOv2 (diversity, drift) embeddings.

Images are float tensors in [0, 1], shape (B, 3, H, W) (SD decoder output after clamping).
"""
from pathlib import Path

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

DEV = "cuda"
CK = Path("checkpoints/rl")
CLIP_MEAN = (0.48145466, 0.4578275, 0.40821073)
CLIP_STD = (0.26862954, 0.26130258, 0.27577711)


def make_trunk(dim=768, K1=9):
    """Same layout as phase_c_lowrank.Shared.trunk (dropout is inactive in eval)."""
    return nn.Sequential(nn.Dropout(0.1), nn.Linear(dim, 512), nn.GELU(), nn.Dropout(0.2), nn.Linear(512, K1))


def make_siglip_head(dim=1152):
    """Same layout as phase_b_critics.make_head('mlp')."""
    return nn.Sequential(nn.Dropout(0.1), nn.Linear(dim, 512), nn.GELU(), nn.Dropout(0.2), nn.Linear(512, 1))


def _resize_crop(x, size, mean, std, interp="bicubic"):
    """open_clip-style preprocessing for square-ish images: resize shortest side to `size`, center-crop, normalise."""
    h, w = x.shape[-2:]
    s = size / min(h, w)
    x = F.interpolate(x, size=(max(size, round(h * s)), max(size, round(w * s))), mode=interp, antialias=True,
                      align_corners=False)
    h, w = x.shape[-2:]
    t, l = (h - size) // 2, (w - size) // 2
    x = x[..., t:t + size, l:l + size].clamp(0, 1)
    m = torch.tensor(mean, device=x.device).view(1, 3, 1, 1)
    sd = torch.tensor(std, device=x.device).view(1, 3, 1, 1)
    return (x - m) / sd


class ClipEncoder:
    def __init__(self):
        import open_clip
        self.model, _, self.prep = open_clip.create_model_and_transforms("ViT-L-14-quickgelu", pretrained="openai")
        self.model.eval().to(DEV).requires_grad_(False)

    @torch.no_grad()
    def __call__(self, x):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            e = self.model.encode_image(_resize_crop(x.float(), 224, CLIP_MEAN, CLIP_STD)).float()
        return F.normalize(e, dim=-1)


class TasteReward:
    """r(x) = z . U(f(x)). `z` (9,) numpy/tensor. Also returns the 9 axis scores for logging."""

    def __init__(self, z, clip=None):
        self.clip = clip or ClipEncoder()
        self.trunk = make_trunk().to(DEV)
        self.trunk.load_state_dict(torch.load(CK / "trunk.pt"))
        self.trunk.eval().requires_grad_(False)
        self.z = torch.as_tensor(np.asarray(z), dtype=torch.float32, device=DEV)

    @torch.no_grad()
    def axes(self, x=None, emb=None):
        if emb is None:
            emb = self.clip(x)
        return self.trunk(emb)

    @torch.no_grad()
    def __call__(self, x=None, emb=None):
        return self.axes(x, emb) @ self.z


class SiglipEncoder:
    def __init__(self):
        import open_clip
        name = "ViT-SO400M-14-SigLIP2-378"
        self.model, _, self.prep = open_clip.create_model_and_transforms(name, pretrained="webli")
        self.tok = open_clip.get_tokenizer(name)
        self.model.eval().to(DEV).requires_grad_(False)
        n = self.prep.transforms[-1]
        self.mean, self.std = tuple(n.mean), tuple(n.std)
        self.size = 378

    @torch.no_grad()
    def image(self, x):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            e = self.model.encode_image(_resize_crop(x.float(), self.size, self.mean, self.std, "bilinear")).float()
        return F.normalize(e, dim=-1)

    @torch.no_grad()
    def text(self, prompts):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            e = self.model.encode_text(self.tok(prompts).to(DEV)).float()
        return F.normalize(e, dim=-1)


class SiglipCritic:
    """Held-out personal critic (Phase B style): s(x) = beta * zscore(head(e)) + w . e, e = SigLIP2 embedding."""

    def __init__(self, siglip=None, path=CK / "siglip_critic.pt"):
        self.enc = siglip or SiglipEncoder()
        ck = torch.load(path)
        self.head = make_siglip_head().to(DEV)
        self.head.load_state_dict(ck["head"])
        self.head.eval().requires_grad_(False)
        self.m, self.s = ck["head_mean"], ck["head_std"]
        self.theta = ck["theta"].float().to(DEV)  # [beta, w (1152)]

    @torch.no_grad()
    def __call__(self, x=None, emb=None):
        if emb is None:
            emb = self.enc.image(x)
        c = (self.head(emb).squeeze(-1) - self.m) / self.s
        return self.theta[0] * c + emb @ self.theta[1:]

    @torch.no_grad()
    def consensus(self, emb):
        return (self.head(emb).squeeze(-1) - self.m) / self.s


class DinoEncoder:
    def __init__(self):
        import timm
        self.model = timm.create_model("vit_large_patch14_reg4_dinov2.lvd142m", pretrained=True, num_classes=0)
        self.model.eval().to(DEV).requires_grad_(False)
        cfg = timm.data.resolve_data_config({}, model=self.model)
        self.mean, self.std = cfg["mean"], cfg["std"]
        self.size = cfg["input_size"][-1]

    @torch.no_grad()
    def __call__(self, x):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            e = self.model(_resize_crop(x.float(), self.size, self.mean, self.std)).float()
        return F.normalize(e, dim=-1)


def load_user(path=CK / "user.pt"):
    """Returns dict with z_user, z_cons (= population mu), and fit details (made by rl_setup.py)."""
    return torch.load(path, weights_only=False)
